24	template <class Element, class ElementRandom>
25	void GenRandomData(Element& data, ElementRandom low, ElementRandom high)
26	{
27	    ElementRandom randomValue =
28	        low + (static_cast<ElementRandom>(rand()) / static_cast<ElementRandom>(RAND_MAX)) * (high - low);
29	    data = static_cast<Element>(randomValue);
30	}
31	
32	template <class Element, class ElementRandom>
33	void FillRandomData(std::vector<Element>& data, ElementRandom low, ElementRandom high)
34	{
