19	namespace Catlass::golden {
20	
21	struct ErrorMetrics {
22	    bool passed;      // true if error ratios meet criteria
23	    double mareRatio; // Max Absolute Relative Error ratio(hostC / hostCpu)
24	    double mereRatio; // Mean Absolute Relative Error ratio(hostC / hostCpu)
25	    double rmseRatio; // Root Mean Squared Error ratio(hostC / hostCpu)
26	};
