28	// Compute error metrics for NPU result vs CPU result against high-precision golden reference
29	// hostC: NPU output, hostCpu: same-precision CPU result, hostGolden: high-precision reference
30	template <class ElementC, class ElementCpu, class ElementGolden>
31	ErrorMetrics ComputeErrorMetrics(
32	    const std::vector<ElementC>& hostC, const std::vector<ElementCpu>& hostCpu,
33	    const std::vector<ElementGolden>& hostGolden, double mareThreshold = 5, double mereThreshold = 1.5,
34	    double rmseThreshold = 1.5)
35	{
36	    const double epsilon = 1e-7;
37	    size_t n = hostC.size();
38	    if (n == 0 || hostCpu.size() != n || hostGolden.size() != n) {
39	        return {false, 0.0, 0.0, 0.0};
40	    }
41	
42	    // Compute error metrics for hostC against hostGolden
43	    double maxRelativeErrorC = 0.0;
44	    double sumRelativeErrorC = 0.0;
45	    double sumSquaredErrorC = 0.0;
46	
47	    // Compute error metrics for hostCpu against hostGolden
48	    double maxRelativeErrorCpu = 0.0;
49	    double sumRelativeErrorCpu = 0.0;
50	    double sumSquaredErrorCpu = 0.0;
51	
52	    for (size_t i = 0; i < n; ++i) {
53	        double cVal = static_cast<double>(hostC[i]);
54	        double cpuVal = static_cast<double>(hostCpu[i]);
55	        double goldenVal = static_cast<double>(hostGolden[i]);
56	
57	        // Error for hostC
58	        double diffC = std::fabs(cVal - goldenVal);
59	        double relativeErrorC = diffC / (std::fabs(goldenVal) + epsilon);
60	        maxRelativeErrorC = std::max(maxRelativeErrorC, relativeErrorC);
61	        sumRelativeErrorC += relativeErrorC;
62	        sumSquaredErrorC += diffC * diffC;
63	
64	        // Error for hostCpu
65	        double diffCpu = std::fabs(cpuVal - goldenVal);
66	        double relativeErrorCpu = diffCpu / (std::fabs(goldenVal) + epsilon);
67	        maxRelativeErrorCpu = std::max(maxRelativeErrorCpu, relativeErrorCpu);
68	        sumRelativeErrorCpu += relativeErrorCpu;
69	        sumSquaredErrorCpu += diffCpu * diffCpu;
70	    }
71	
72	    double mareC = maxRelativeErrorC;
73	    double mereC = sumRelativeErrorC / n;
74	    double rmseC = std::sqrt(sumSquaredErrorC / n);
75	
76	    double mareCpu = maxRelativeErrorCpu;
77	    double mereCpu = sumRelativeErrorCpu / n;
78	    double rmseCpu = std::sqrt(sumSquaredErrorCpu / n);
79	
80	    // Compute error ratios (hostC / hostCpu)
81	    double mareRatio = (mareCpu > 0) ? mareC / mareCpu : 0.0;
82	    double mereRatio = (mereCpu > 0) ? mereC / mereCpu : 0.0;
83	    double rmseRatio = (rmseCpu > 0) ? rmseC / rmseCpu : 0.0;
84	
85	    bool passed = (mareRatio <= mareThreshold && mereRatio <= mereThreshold && rmseRatio <= rmseThreshold);
86	
87	    return {passed, mareRatio, mereRatio, rmseRatio};
88	}
