90	template <class ElementResult, class ElementCompare>
91	std::vector<uint64_t> CompareData(
92	    const std::vector<ElementResult>& result, const std::vector<ElementCompare>& expect, uint32_t computeNum)
93	{
94	    const uint32_t computeNumThreshold = 2048;
95	    const float rtolGeneral = 1.0f / 256;
96	    const float rtolOverThreshold = 1.0f / 128;
97	
98	    float rtol = computeNum < computeNumThreshold ? rtolGeneral : rtolOverThreshold;
99	    std::vector<uint64_t> errorIndices;
100	    for (uint64_t i = 0; i < result.size(); ++i) {
101	        ElementCompare actualValue = static_cast<ElementCompare>(result[i]);
102	        ElementCompare expectValue = expect[i];
103	        ElementCompare diff = std::fabs(actualValue - expectValue);
104	        if (diff > rtol * std::max(1.0f, std::fabs(expectValue))) {
105	            errorIndices.push_back(i);
106	        }
107	    }
108	    return errorIndices;
109	}
