111	template <>
112	std::vector<uint64_t> CompareData(
113	    const std::vector<int32_t>& result, const std::vector<int32_t>& expect, uint32_t computeNum)
114	{
115	    using ElementCompare = int32_t;
116	    std::vector<uint64_t> errorIndices;
117	    for (uint64_t i = 0; i < result.size(); ++i) {
118	        ElementCompare actualValue = static_cast<ElementCompare>(result[i]);
119	        ElementCompare expectValue = expect[i];
120	        ElementCompare diff = std::abs(actualValue - expectValue);
121	        if (diff != 0) {
122	            errorIndices.push_back(i);
123	        }
124	    }
125	    return errorIndices;
126	}
