128	template <class ElementResult>
129	std::vector<uint64_t> CompareDataBfloat16(
130	    const std::vector<ElementResult>& result, const std::vector<float>& expect, uint32_t computeNum)
131	{
132	    /*
133	     * 高性能 浮点计算通过标准：
134	     * 计算次数<2048, errThres = 2^{-7}
135	     * 大于>2048, errThres = 2^{-6}
136	     *
137	     * 当$abs(golden)>=smallValThres$时，使用相对误差校验：
138	     * $$
139	     *  RE = \frac { abs(actual - golden)} { abs{golden} + 1e^{-7}} \le errThres
140	     * $$
141	     * 反之，采用绝对误差校验：
142	     * $$
143	     *  AE= abs(actual - golden) \le errThres
144	     * $$
145	     * 判断公式：
146	     * $$
147	     *  \left \| actual - expected \right\| \le
148	          errThres \times \max(smallValThres, abs(expected))
149	     * $$
150	    */
151	    using ElementCompare = float;
152	    const uint32_t computeNumThreshold = 2048;
153	    const float smallValThres = 1.0f / 256;
154	    const float rtolGeneral = 1.0f / 128;
155	    const float rtolOverThreshold = 1.0f / 64;
156	
157	    float rtol = computeNum < computeNumThreshold ? rtolGeneral : rtolOverThreshold;
158	    std::vector<uint64_t> errorIndices;
159	    for (uint64_t i = 0; i < result.size(); ++i) {
160	        ElementCompare actualValue = static_cast<ElementCompare>(result[i]);
161	        ElementCompare expectValue = expect[i];
162	        ElementCompare diff = std::fabs(actualValue - expectValue);
163	        if (diff > rtol * std::max(smallValThres, std::fabs(expectValue))) {
164	            errorIndices.push_back(i);
165	        }
166	    }
167	    return errorIndices;
168	}
