170	// Compare for GroupedMatmul slicing M
171	template <class ElementResult, class ElementCompare>
172	std::vector<uint64_t> CompareData(
173	    const std::vector<ElementResult>& result, const std::vector<ElementCompare>& expect, uint32_t computeNum,
174	    uint32_t validNum)
175	{
176	    const uint32_t computeNumThreshold = 2048;
177	    const float rtolGeneral = 1.0f / 256;
178	    const float rtolOverThreshold = 1.0f / 128;
179	
180	    float rtol = computeNum < computeNumThreshold ? rtolGeneral : rtolOverThreshold;
181	    std::vector<uint64_t> errorIndices;
182	    for (uint64_t i = 0; i < validNum; ++i) {
183	        ElementCompare actualValue = static_cast<ElementCompare>(result[i]);
184	        ElementCompare expectValue = expect[i];
185	        ElementCompare diff = std::fabs(actualValue - expectValue);
186	        if (diff > rtol * std::max(1.0f, std::fabs(expectValue))) {
187	            errorIndices.push_back(i);
188	        }
189	    }
190	    return errorIndices;
191	}
192	
193	// Compare for GroupedMatmul slicing K
194	template <class ElementResult, class ElementCompare, class T>
195	std::vector<uint64_t> CompareData(
196	    const std::vector<ElementResult>& result, const std::vector<ElementCompare>& expect, uint32_t computeNum,
197	    const std::vector<T>& groupList, uint32_t stride)
198	{
199	    const uint32_t computeNumThreshold = 2048;
200	    const float rtolGeneral = 1.0f / 256;
201	    const float rtolOverThreshold = 1.0f / 128;
202	
203	    float rtol = computeNum < computeNumThreshold ? rtolGeneral : rtolOverThreshold;
204	    std::vector<uint64_t> errorIndices;
205	    T prevGroupValue = 0;
206	    uint64_t currentIndex = 0;
207	    for (const auto& groupValue : groupList) {
208	        if (groupValue == prevGroupValue) {
209	            currentIndex += stride;
210	            prevGroupValue = groupValue;
211	            continue;
212	        }
213	        for (uint64_t i = 0; i < stride; ++i) {
214	            if (currentIndex >= result.size())
215	                break;
216	            ElementCompare actualValue = static_cast<ElementCompare>(result[currentIndex]);
217	            ElementCompare expectValue = expect[currentIndex];
218	            ElementCompare diff = std::fabs(actualValue - expectValue);
219	            if (diff > rtol * std::max(1.0f, std::fabs(expectValue))) {
220	                errorIndices.push_back(i);
221	            }
222	            currentIndex++;
223	        }
224	        prevGroupValue = groupValue;
225	    }
226	    return errorIndices;
227	}
