23	// simple matmul
24	template <class ElementA, class LayoutA, class ElementB, class LayoutB, class ElementGolden, class LayoutGolden>
25	void ComputeMatmul(
26	    const GemmCoord& problemShape, const std::vector<ElementA>& dataA, const LayoutA& layoutA,
27	    const std::vector<ElementB>& dataB, const LayoutB& layoutB, std::vector<ElementGolden>& dataGolden,
28	    const LayoutGolden& layoutGolden)
29	{
30	    for (uint32_t i = 0; i < problemShape.m(); ++i) {
31	        for (uint32_t j = 0; j < problemShape.n(); ++j) {
32	            size_t offsetGolden = layoutGolden.GetOffset(MakeCoord(i, j));
33	            ElementGolden accumulator = 0;
34	            for (uint32_t k = 0; k < problemShape.k(); ++k) {
35	                size_t offsetA = 0;
36	                if constexpr (std::is_same_v<LayoutA, layout::VectorLayout>) {
37	                    offsetA = layoutA.GetOffset(MakeCoord(k));
38	                } else {
39	                    offsetA = layoutA.GetOffset(MakeCoord(i, k));
40	                }
41	                size_t offsetB = layoutB.GetOffset(MakeCoord(k, j));
42	                accumulator += static_cast<ElementGolden>(dataA[offsetA]) * static_cast<ElementGolden>(dataB[offsetB]);
43	            }
44	            dataGolden[offsetGolden] = static_cast<ElementGolden>(accumulator);
45	        }
46	    }
47	}
