51	// simple gemm
52	template <
53	    typename Element, class ElementA, class LayoutA, class ElementB, class LayoutB, class ElementC, class LayoutC,
54	    class ElementGolden, class LayoutGolden>
55	void ComputeGemm(
56	    const GemmCoord& problemShape, Element alpha, Element beta, const std::vector<ElementA>& dataA,
57	    const LayoutA& layoutA, const std::vector<ElementB>& dataB, const LayoutB& layoutB,
58	    const std::vector<ElementC>& dataC, const LayoutC& layoutC, std::vector<ElementGolden>& dataGolden,
59	    const LayoutGolden& layoutGolden)
60	{
61	    for (uint32_t i = 0; i < problemShape.m(); ++i) {
62	        for (uint32_t j = 0; j < problemShape.n(); ++j) {
63	            size_t offsetGolden = layoutGolden.GetOffset(MakeCoord(i, j));
64	            ElementGolden accumulator = 0;
65	            for (uint32_t k = 0; k < problemShape.k(); ++k) {
66	                size_t offsetA = layoutA.GetOffset(MakeCoord(i, k));
67	                size_t offsetB = layoutB.GetOffset(MakeCoord(k, j));
68	                accumulator += static_cast<ElementGolden>(alpha) * static_cast<ElementGolden>(dataA[offsetA]) *
69	                               static_cast<ElementGolden>(dataB[offsetB]);
70	            }
71	            dataGolden[offsetGolden] =
72	                static_cast<ElementGolden>(beta) * static_cast<ElementGolden>(dataC[offsetGolden]) +
73	                static_cast<ElementGolden>(accumulator);
74	        }
75	    }
76	}
