78	template <
79	    typename Element, class ElementA, class LayoutA, class ElementX, class LayoutX, class ElementY, class LayoutY,
80	    class ElementGolden, class LayoutGolden>
81	void ComputeGemv(
82	    const Catlass::GemvCoord& problemShape, Element alpha, Element beta, const std::vector<ElementA>& dataA,
83	    const LayoutA& layoutA, const std::vector<ElementX>& dataX, const LayoutX& layoutX,
84	    const std::vector<ElementY>& dataY, const LayoutY& layoutY, std::vector<ElementGolden>& dataGolden,
85	    const LayoutGolden& layoutGolden)
86	{
87	    for (uint32_t i = 0; i < problemShape.m(); ++i) {
88	        size_t offsetGolden = layoutGolden.GetOffset(MakeCoord(i));
89	        ElementGolden accumulator = 0;
90	        for (uint32_t k = 0; k < problemShape.n(); ++k) {
91	            size_t offsetA = layoutA.GetOffset(MakeCoord(i, k));
92	            size_t offsetX = layoutX.GetOffset(MakeCoord(k));
93	            accumulator += static_cast<ElementGolden>(alpha) * static_cast<ElementGolden>(dataA[offsetA]) *
94	                           static_cast<ElementGolden>(dataX[offsetX]);
95	        }
96	        size_t offsetY = layoutY.GetOffset(MakeCoord(i));
97	        dataGolden[offsetGolden] = static_cast<ElementGolden>(beta) * static_cast<ElementGolden>(dataY[offsetY]) +
98	                                   static_cast<ElementGolden>(accumulator);
99	    }
100	}
