102	// simple grouped gemm
103	template <
104	    typename Element, class ElementA, class LayoutA, class ElementB, class LayoutB, class ElementC, class LayoutC,
105	    class ElementGolden, class LayoutGolden>
106	void ComputeGroupGemm(
107	    uint32_t problemCount, const std::vector<GemmCoord>& problemShapeList, const std::vector<Element>& alphaList,
108	    const std::vector<Element>& betaList, const std::vector<ElementA>& dataA, const std::vector<LayoutA>& layoutAList,
109	    const std::vector<ElementB>& dataB, const std::vector<LayoutB>& layoutBList, const std::vector<ElementC>& dataC,
110	    const std::vector<LayoutC>& layoutCList, std::vector<ElementGolden>& dataGolden,
111	    const std::vector<LayoutGolden>& layoutGoldenList)
112	{
113	    size_t inGroupOffsetA = 0;
114	    size_t inGroupOffsetB = 0;
115	    size_t inGroupOffsetC = 0;
116	    size_t inGroupOffsetGolden = 0;
117	
118	    for (uint32_t inGroupId = 0; inGroupId < problemCount; ++inGroupId) {
119	        GemmCoord problemShape = problemShapeList[inGroupId];
120	        Element alpha = alphaList[inGroupId];
121	        Element beta = betaList[inGroupId];
122	
123	        for (uint32_t i = 0; i < problemShape.m(); ++i) {
124	            for (uint32_t j = 0; j < problemShape.n(); ++j) {
125	                size_t offsetGolden = inGroupOffsetGolden + layoutGoldenList[inGroupId].GetOffset(MakeCoord(i, j));
126	                ElementGolden accumulator = 0;
127	
128	                for (uint32_t k = 0; k < problemShape.k(); ++k) {
129	                    size_t offsetA = inGroupOffsetA + layoutAList[inGroupId].GetOffset(MakeCoord(i, k));
130	                    size_t offsetB = inGroupOffsetB + layoutBList[inGroupId].GetOffset(MakeCoord(k, j));
131	                    accumulator += static_cast<ElementGolden>(alpha) * static_cast<ElementGolden>(dataA[offsetA]) *
132	                                   static_cast<ElementGolden>(dataB[offsetB]);
133	                }
134	
135	                size_t offsetC = inGroupOffsetC + layoutCList[inGroupId].GetOffset(MakeCoord(i, j));
136	                dataGolden[offsetGolden] =
137	                    static_cast<ElementGolden>(beta) * static_cast<ElementGolden>(dataC[offsetC]) +
138	                    static_cast<ElementGolden>(accumulator);
139	            }
140	        }
141	
142	        inGroupOffsetA += static_cast<size_t>(problemShape.m()) * problemShape.k();
143	        inGroupOffsetB += static_cast<size_t>(problemShape.k()) * problemShape.n();
144	        inGroupOffsetC += static_cast<size_t>(problemShape.m()) * problemShape.n();
145	        inGroupOffsetGolden += static_cast<size_t>(problemShape.m()) * problemShape.n();
146	    }
147	}
