150	// simple batched matmul
151	template <class ElementA, class LayoutA, class ElementB, class LayoutB, class ElementGolden, class LayoutGolden>
152	void ComputeBatchedMatmul(
153	    const uint32_t batchedCount, const GemmCoord& problemShape, const std::vector<ElementA>& dataA,
154	    const LayoutA& layoutA, const std::vector<ElementB>& dataB, const LayoutB& layoutB,
155	    std::vector<ElementGolden>& dataC, const LayoutGolden& layoutGolden)
156	{
157	    for (uint32_t batchId = 0; batchId < batchedCount; ++batchId) {
158	        size_t batchOffsetA = static_cast<size_t>(problemShape.m()) * problemShape.k() * batchId;
159	        size_t batchOffsetB = static_cast<size_t>(problemShape.k()) * problemShape.n() * batchId;
160	        size_t batchoffsetGolden = static_cast<size_t>(problemShape.m()) * problemShape.n() * batchId;
161	        for (uint32_t i = 0; i < problemShape.m(); ++i) {
162	            for (uint32_t j = 0; j < problemShape.n(); ++j) {
163	                size_t offsetGolden = layoutGolden.GetOffset(MakeCoord(i, j)) + batchoffsetGolden;
164	                ElementGolden accumulator = 0;
165	                for (uint32_t k = 0; k < problemShape.k(); ++k) {
166	                    size_t offsetA = layoutA.GetOffset(MakeCoord(i, k)) + batchOffsetA;
167	                    size_t offsetB = layoutB.GetOffset(MakeCoord(k, j)) + batchOffsetB;
168	                    accumulator +=
169	                        static_cast<ElementGolden>(dataA[offsetA]) * static_cast<ElementGolden>(dataB[offsetB]);
170	                }
171	                dataC[offsetGolden] = static_cast<ElementGolden>(accumulator);
172	            }
173	        }
174	    }
175	}
