234	template <class ElementGroupList, class ElementScale, class LayoutB>
235	void ComputeGroupedMatmulFixpipeDequant(
236	    const GemmCoord& problemShape, uint32_t problemCount, const std::vector<ElementGroupList>& groupList,
237	    const std::vector<int8_t>& dataA, const layout::RowMajor& layoutA, const std::vector<int8_t>& dataB,
238	    const LayoutB& layoutB, std::vector<float>& dataGolden, const layout::RowMajor& layoutGolden,
239	    const int32_t quantMode, const ElementScale& dataScale = 1.0,
240	    const std::vector<ElementScale>& dataPerChannelScale = {})
241	{
242	    size_t groupOffsetB = 0;
243	    size_t groupOffsetScale = 0;
244	    uint32_t startRow = 0;
245	    for (uint32_t inGroupId = 0; inGroupId < problemCount; ++inGroupId) {
246	        for (uint32_t i = startRow; i < groupList[inGroupId]; ++i) {
247	            for (uint32_t j = 0; j < problemShape.n(); ++j) {
248	                size_t offsetGolden = layoutGolden.GetOffset(MakeCoord(i, j));
249	                int32_t accumulator = 0;
250	                for (uint32_t k = 0; k < problemShape.k(); ++k) {
251	                    size_t offsetA = layoutA.GetOffset(MakeCoord(i, k));
252	                    size_t offsetB = groupOffsetB + layoutB.GetOffset(MakeCoord(k, j));
253	                    accumulator += static_cast<int32_t>(dataA[offsetA]) * static_cast<int32_t>(dataB[offsetB]);
254	                }
255	                if (quantMode == 0) { // perTensor
256	                    dataGolden[offsetGolden] = static_cast<float>(accumulator) * static_cast<float>(dataScale);
257	                } else if (quantMode == 1) { // perChannel
258	                    dataGolden[offsetGolden] =
259	                        static_cast<float>(accumulator) * static_cast<float>(dataPerChannelScale[j]);
260	                } else {
261	                    std::cerr << "[ERROR] quantMode must be '0' or '1'." << std::endl;
262	                    return;
263	                }
264	            }
265	        }
266	        groupOffsetB += static_cast<size_t>(problemShape.k()) * problemShape.n();
267	        startRow = groupList[inGroupId];
268	    }
269	}
