282	    for (uint32_t inGroupId = 0; inGroupId < problemCount; ++inGroupId) {
283	        for (uint32_t i = startRow; i < groupList[inGroupId]; ++i) {
284	            for (uint32_t j = 0; j < problemShape.n(); ++j) {
285	                size_t offsetGolden = layoutGolden.GetOffset(MakeCoord(i, j));
286	                int32_t accumulator = 0;
287	                for (uint32_t k = 0; k < problemShape.k(); ++k) {
