291	                }
292	                dataGolden[offsetGolden] = static_cast<float>(accumulator) *
293	                                           static_cast<float>(dataScale[groupOffsetScale + j]) *
294	                                           static_cast<float>(dataPerTokenScale[i]);
295	            }
296	        }
297	        groupOffsetB += static_cast<size_t>(problemShape.k()) * problemShape.n();
