327	void ComputeGroupedMatmulSliceKPerTokenDequant(
328	    const GemmCoord& problemShape, uint32_t problemCount, const std::vector<ElementGroupList>& groupList,
329	    const std::vector<int8_t>& dataA, const layout::ColumnMajor& layoutA, const std::vector<int8_t>& dataB,
