406	template <class ElementT>
407	struct Relu {
408	    ElementT operator()(ElementT val) const
409	    {
410	        return val < ElementT(0) ? ElementT(0) : val;
411	    }
412	};
413	
414	template <class ElementT>
415	struct Sigmoid {
416	    ElementT operator()(ElementT val) const
417	    {
418	        // 使用类型安全的数学函数调用
419	        using std::exp; // 启用ADL查找
420	        const ElementT one = static_cast<ElementT>(1);
421	        return one / (one + exp(-val)); // 全部使用ElementT类型
422	    }
423	};
424	
425	template <class ElementT>
426	struct Silu {
427	    ElementT operator()(ElementT val) const
428	    {
429	        return val * Sigmoid<ElementT>{}(val);
430	    }
431	};
432	
433	template <class ElementT>
434	struct Gelu {
435	    ElementT operator()(ElementT val) const
436	    {
437	        static constexpr ElementT kScale = 1.59576912; // 2 * sqrt(2/π)
438	        static constexpr ElementT kCubicCoef = 0.044715;
439	
440	        // 更稳定的计算方式
441	        const ElementT x_cubed = val * val * val;
442	        const ElementT inner = val + kCubicCoef * x_cubed;
443	
444	        return val * Sigmoid<ElementT>{}(kScale * inner);
445	    }
446	};
